import{_ as l,a0 as r,w as o,s as d,I as n,x as e,a1 as i,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"從 Linux 終端打印文件 | LCTT x X-CMD","titleTemplate":false,"description":"從 Linux 終端打印文件 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"從 Linux 終端打印文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"從 Linux 終端打印文件 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210903 Print files from your Linux terminal","title":"從 Linux 終端打印文件","tag":"202112","desc":""},"relativePath":"202112/20210903 Print files from your Linux terminal.md","filePath":"[post].md"}'),u={name:"202112/20210903 Print files from your Linux terminal.md"};function c(h,s,g,f,b,k){const a=r("Link");return o(),d("div",null,[s[26]||(s[26]=n("h1",{id:"從-linux-終端打印文件",tabindex:"-1"},[e("從 Linux 終端打印文件 "),n("a",{class:"header-anchor",href:"#從-linux-終端打印文件","aria-label":"Permalink to “從 Linux 終端打印文件”"},"​")],-1)),s[27]||(s[27]=n("blockquote",null,[n("p",null,"使用 lpr 命令在終端中打印文件。")],-1)),s[28]||(s[28]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202112/20/135809an6s6bxyg7sjnwyq.jpg",alt:""})],-1)),n("p",null,[i(a,{href:"https://opensource.com/article/21/8/setup-your-printer-linux"},{default:t(()=>[...s[0]||(s[0]=[e("在 Linux 上打印很容易",-1)])]),_:1}),s[1]||(s[1]=e("，但有時感覺要做很多工作，比如啓動應用程序、打開文件、在菜單中找到打印選項，單擊確認按鈕等等。當你是一個終端用户時，通常希望使用簡單的觸發器執行復雜的操作。打印很複雜，但沒有什麼比 ",-1)),s[2]||(s[2]=n("code",null,"lpr",-1)),s[3]||(s[3]=e(" 命令更簡單了。",-1))]),s[29]||(s[29]=p(`<h3 id="使用-lpr-命令打印" tabindex="-1">使用 lpr 命令打印 <a class="header-anchor" href="#使用-lpr-命令打印" aria-label="Permalink to “使用 lpr 命令打印”">​</a></h3><p>使用 <code>lpr</code> 命令在終端打印文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpr myfile.odt</span></span></code></pre></div><p>如果失敗的話，你需要設置默認打印機或手動指定打印機。</p><h3 id="設置默認打印機" tabindex="-1">設置默認打印機 <a class="header-anchor" href="#設置默認打印機" aria-label="Permalink to “設置默認打印機”">​</a></h3><p>根據我在 1984 年印刷的 Berkeley 4.2 手冊的舊版本中找到的資料，<code>lpr</code> 命令會分頁並將文件發送到打印機池，後者將數據傳輸到稱為 <ruby>行式打印機<rt>line printer</rt></ruby> 的東西。</p><p><img src="https://opensource.com/sites/default/files/berkeley-1984-lpr.jpeg" alt="顯示 LPR 命令信息的頁面"></p><p>現在，最初的 <code>lpr</code> 命令已經無法滿足，因為現代計算機可以訪問多台打印機，而且是那些比點陣行式打印機複雜得多的打印機。現在有一個稱為<ruby>通用 Unix 打印系統<rt>Common Unix Printing System</rt></ruby>（CUPS）子系統，可以跟蹤你的計算機可以訪問的所有打印機，計算機應該使用哪個驅動程序與每台打印機通信，默認使用哪台打印機等等。 CUPS 捆綁提供的 <code>lpr.cups</code> 或 <code>lpr-cups</code> 命令通常以符號鏈接到 <code>lpr</code>，允許你首先借助 CUPS 配置從終端打印。</p><p>使用 <code>lpr</code> 打印文件，你應該首先設置默認打印機。你可以在系統的打印機設置中設置：</p><p><img src="https://opensource.com/sites/default/files/printer-default.jpeg" alt="設置默認打印機對話框"></p><p>或者，你也可以使用 <code>lpadmin</code> 命令設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lpadmin -d HP_LaserJet_P2015_Series</span></span>
<span class="line"><span>$ lpstat -v</span></span>
<span class="line"><span>device for HP_LaserJet_P2015_Series: ipp://10.0.1.222:631/printers/HP_LaserJet_P2015_Series</span></span></code></pre></div><h3 id="使用環境變量設置" tabindex="-1">使用環境變量設置 <a class="header-anchor" href="#使用環境變量設置" aria-label="Permalink to “使用環境變量設置”">​</a></h3>`,13)),n("p",null,[s[5]||(s[5]=e("你不能在沒有管理員賬户的系統上設置默認打印機，因為更改打印機默認設置是一項特權任務。在 ",-1)),s[6]||(s[6]=n("code",null,"lpr",-1)),s[7]||(s[7]=e(" 藉助 CUPS 找到目標打印機前，它會在系統中查詢 ",-1)),s[8]||(s[8]=n("code",null,"PRINTER",-1)),s[9]||(s[9]=e()),i(a,{href:"https://opensource.com/article/19/8/what-are-environment-variables"},{default:t(()=>[...s[4]||(s[4]=[e("環境變量",-1)])]),_:1}),s[10]||(s[10]=e("。",-1))]),s[30]||(s[30]=p(`<p>在本例中，<code>HP_LaserJet_P2015_Series</code> 是打印機的名稱。將 <code>PRINTER</code> 設置為該值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ PRINTER=HP_LaserJet_P2015_Series</span></span>
<span class="line"><span>$ export PRINTER</span></span></code></pre></div><p>一旦設置了 <code>PRINTER</code> 變量，你就可以打印了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpr myfile.pdf</span></span></code></pre></div><h3 id="獲取連接的打印機列表" tabindex="-1">獲取連接的打印機列表 <a class="header-anchor" href="#獲取連接的打印機列表" aria-label="Permalink to “獲取連接的打印機列表”">​</a></h3><p>你可以使用 <code>lpstat</code> 命令查看所有連接到系統接受打印任務的打印機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpstat -a</span></span>
<span class="line"><span>HP_LaserJet_P2015_Series accepting requests since Sun 1 Aug 2021 10:11:02 PM NZST</span></span>
<span class="line"><span>r1060 accepting requests since Wed 18 Aug 2021 04:43:57 PM NZST</span></span></code></pre></div><h3 id="打印到任意一台打印機" tabindex="-1">打印到任意一台打印機 <a class="header-anchor" href="#打印到任意一台打印機" aria-label="Permalink to “打印到任意一台打印機”">​</a></h3><p>將打印機添加到系統後，並且現在你知道如何識別它們了，你可以打印到其中任何一台，無論你是否設置了默認打印機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpr -P HP_LaserJet_P2015_Series myfile.txt</span></span></code></pre></div><h3 id="如何定義打印機" tabindex="-1">如何定義打印機 <a class="header-anchor" href="#如何定義打印機" aria-label="Permalink to “如何定義打印機”">​</a></h3><p>CUPS 有一個友好的前端頁面，可通過 Web 瀏覽器如 Firefox 訪問。雖然它使用 Web 瀏覽器作為用户界面，但它實際上是在本機（一個稱為 <code>localhost</code> 的位置）的 631 端口上提供服務。CUPS 管理連接到計算機的打印機，並將其配置存儲在 <code>/etc/cups/priters.conf</code> 中。</p><p><code>printers.conf</code> 文件包含詳細描述計算機可以訪問的打印設備的定義。不要直接編輯它，但如果你想這樣做，你必須先停止 <code>cupsd</code> 守護進程。</p><p>一個典型的文件定義如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;Printer r1060&gt;</span></span>
<span class="line"><span>  Info Ricoh 1060</span></span>
<span class="line"><span>  Location Downstairs</span></span>
<span class="line"><span>  MakeModel Ricoh Aficio 1060 - CUPS+Gutenprint v5.2.6</span></span>
<span class="line"><span>  DeviceURI lpd://192.168.4.8</span></span>
<span class="line"><span>  State Idle</span></span>
<span class="line"><span>  StateTime 1316011347</span></span>
<span class="line"><span>  Type 12308</span></span>
<span class="line"><span>  Filter application/vnd.cups-raw 0 -</span></span>
<span class="line"><span>  Filter application/vnd.cups-raster 100 rastertogutenprint.5.2</span></span>
<span class="line"><span>  Accepting Yes</span></span>
<span class="line"><span>  Shared No</span></span>
<span class="line"><span>  JobSheets none none</span></span>
<span class="line"><span>  QuotaPeriod 0</span></span>
<span class="line"><span>  PageLimit 0</span></span>
<span class="line"><span>  KLimit 0</span></span>
<span class="line"><span>  OpPolicy default</span></span>
<span class="line"><span>  ErrorPolicy stop-printer</span></span>
<span class="line"><span>&lt;/Printer&gt;</span></span></code></pre></div><p>在本例中，打印機的名稱是 <code>r1060</code>，即 “Ricoh Aficio 1060”。</p><p><code>MakeModel</code> 屬性是從 <code>lpinfo</code> 命令中提取的，該命令列出了系統上所有可用的打印機驅動程序。假設你知道要打印到 Ricoh Aficio 1060，那麼你會發出以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpinfo -m | grep 1060</span></span>
<span class="line"><span>gutenprint.5.2://brother-hl-1060/expert Brother HL-1060 - CUPS+Gutenprint v5.2.11</span></span>
<span class="line"><span>gutenprint.5.2://ricoh-afc_1060/expert Ricoh Aficio 1060 - CUPS+Gutenprint v5.2.11</span></span></code></pre></div><p>它會列出已安裝的相關驅動程序。</p><p><code>MakeModel</code> 屬性是結果的後半部分。在本例中為 <code>Ricoh Aficio 1060 - CUPS+Gutenprint v5.2.11</code>。</p><p><code>DeviceURI</code> 屬性標識打印機在網絡上的位置（或物理位置，例如 USB 端口）。在本例中，它是 <code>lpd://192.168.4.8</code>，因為我使用 <code>lpd</code> 協議將數據發送到一台網絡打印機。在我的另一個系統上，我有一個通過 USB 連接的 HP LaserJect 打印機，因此 <code>DeviceURI</code> 是 <code>hp:/usb/HP_LaserJet_P2015_Series?serial=00CNCJM26429</code>。</p><h3 id="在終端中打印" tabindex="-1">在終端中打印 <a class="header-anchor" href="#在終端中打印" aria-label="Permalink to “在終端中打印”">​</a></h3><p>將作業發送到打印機是一個簡單的過程，只要你瞭解連接到系統的設備以及如何識別它們。在終端打印非常快速、高效，並且易於編寫腳本或作為批處理作業完成。試試看！</p><hr>`,24)),n("p",null,[s[12]||(s[12]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/21/9/print-files-linux"},{default:t(()=>[...s[11]||(s[11]=[e("https://opensource.com/article/21/9/print-files-linux",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[13]||(s[13]=[e("Seth Kenlon",-1)])]),_:1}),s[18]||(s[18]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 譯者：",-1)),i(a,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[15]||(s[15]=[e("MjSeven",-1)])]),_:1}),s[20]||(s[20]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[e("Linux中國",-1)])]),_:1}),s[25]||(s[25]=e(" 榮譽推出",-1))])])}const C=l(u,[["render",c]]);export{x as __pageData,C as default};
